import{_ as o,o as t,c as a,a0 as i}from"./chunks/framework.Bmhw_dvp.js";const g=JSON.parse('{"title":"ZViewerCLI 代理协议","description":"","frontmatter":{},"headers":[],"relativePath":"advanced/cli-protocol.md","filePath":"advanced/cli-protocol.md","lastUpdated":1790783629000}'),s={name:"advanced/cli-protocol.md"};function d(c,e,l,n,r,p){return t(),a("div",null,[...e[0]||(e[0]=[i(`<h1 id="zviewercli-代理协议" tabindex="-1">ZViewerCLI 代理协议 <a class="header-anchor" href="#zviewercli-代理协议" aria-label="Permalink to &quot;ZViewerCLI 代理协议&quot;">​</a></h1><p><a href="https://github.com/Zero-wyc/ZViewerCLI" target="_blank" rel="noreferrer">ZViewerCLI</a> 是一个 Go 编写的独立仓库。它通过 Socket.IO（一种在 WebSocket 之上实现实时双向通信的库）与服务器通信，为浏览器提供两样能力：使用本机 Bilibili Cookie，以及把媒体流经本机代理转发。Cookie 只保存在用户本机，不经过服务器。</p><h2 id="注册流程-v0-2-0-去房间化" tabindex="-1">注册流程（v0.2.0 去房间化） <a class="header-anchor" href="#注册流程-v0-2-0-去房间化" aria-label="Permalink to &quot;注册流程（v0.2.0 去房间化）&quot;">​</a></h2><p>CLI 启动后要先向服务器登记自己，服务器才知道有一个可用的本机代理。注册分五步。</p><ol><li><p>CLI 启动时携带 Engine.IO 握手参数 <code>{&quot;agent&quot;:&quot;zcontrol-cli&quot;}</code> 建立 WebSocket。服务器的 <code>io.use</code> 中间件（Socket.IO 在建立连接前执行的钩子）看到这个参数就直接放行并标记 <code>isCliAgent</code>，绕过通用的 access_token 校验。</p></li><li><p>连接建立后，CLI 发送 <code>cli-register</code> 事件，payload 如下：</p></li></ol><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;proxyUrl&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;http://127.0.0.1:9333&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;agent&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;zviewer-cli&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;version&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;0.2.0&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;user&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;用户名&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><ol start="3"><li><p>服务端只校验必填的 <code>proxyUrl</code>，<strong>忽略任何房间号</strong>（<code>roomId</code> 只是为兼容旧版保留的字段）。同时用 <code>normalizeLocalCliProxyUrl</code> 把 hostname <strong>强制改写为 <code>127.0.0.1</code></strong>（端口和路径保持不变）。这样做是为了防止旧版 CLI 误报页面 host，导致前端 CORS（跨域资源共享，浏览器判断能否跨域请求的规则）失败。</p></li><li><p>服务端把 CLI 记入专用房间 <code>__cli-agents__</code>，这只为聚合查询方便，语义上等于全局注册。随后回 <code>cli-registered</code>，并 <code>io.emit(&#39;cli-agent-available&#39;, agentInfo)</code> <strong>全局广播</strong>。连接没有 <code>isCliAgent</code> 标记或缺少 proxyUrl 时，回 <code>cli-error</code>。</p></li><li><p>CLI 断连时，服务器全局广播 <code>cli-agent-unavailable {socketId}</code>。<code>cli-list-agents</code>（参数可以省略）经 <code>io.in(&#39;__cli-agents__&#39;).fetchSockets()</code> 聚合后返回。</p></li></ol><h2 id="代理的作用范围与可用性" tabindex="-1">代理的作用范围与可用性 <a class="header-anchor" href="#代理的作用范围与可用性" aria-label="Permalink to &quot;代理的作用范围与可用性&quot;">​</a></h2><p>一个 CLI 注册进来之后，谁能用它、它能撑多久、什么时候算可用，都有明确的规则。</p><ul><li><p><strong>一个 CLI 对服务器上所有房间都可用。</strong> 房间里的 CLI 功能开关（音乐视频高画质 <code>musicVideoCli</code> / <code>cliEnabled</code>）打开后会自动使用它，不存在「每个房间各连一个 CLI」的概念。</p></li><li><p><strong>按 user 过滤归属。</strong> 前端的 <code>useCliAgent()</code> 不带参数调用，内部按 <code>authStore</code> 里的登录用户名过滤，只保留满足 <code>!a.user || a.user === username</code> 的代理。不带 <code>user</code> 字段的旧版 CLI 视为公共代理，所有人可见。过滤完成后才写入 cliAgentStore，所以 store 里只有当前用户的代理，<code>getActiveCliProxyUrl</code> 直接取 <code>agents[0].proxyUrl</code> 即可。</p></li><li><p><strong>配置只存在内存里。</strong> CLI 重启后，<code>serverUrl</code> 和 <code>user</code> 都会丢失，只有 Cookie 持久化在 <code>~/.zviewer/config.json</code>，需要从网页端配置页重新带入。</p></li><li><p><strong>可用性只看有没有代理注册进来。</strong> 判定条件是 <code>available = agents.length &gt; 0</code>，不强制要求本地健康检查通过，因为健康检查可能因 CORS 失败，而实际的 HTTP 服务仍然可用。健康检查只在 http 本地页面执行，每 5s 轮询一次 <code>/health</code>；https 页面直接跳过。</p></li></ul><h2 id="本地代理与解析" tabindex="-1">本地代理与解析 <a class="header-anchor" href="#本地代理与解析" aria-label="Permalink to &quot;本地代理与解析&quot;">​</a></h2><p>CLI 在本机启动一个 HTTP 服务，浏览器通过它取到带 Cookie 的媒体流。服务默认绑定 <code>127.0.0.1:9333</code>（可用 <code>-port</code> 改端口），提供这些路由：<code>/health</code>、<code>/api/config</code>、<code>/api/qr</code>、<code>/api/qr/poll</code>（B站扫码登录）、<code>/api/connect</code>、<code>/api/disconnect</code>、<code>/api/bili-info</code>、<code>/api/dash-mpd</code>、<code>/resolve</code>、<code>/proxy</code>。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>浏览器 &lt;video&gt;/&lt;audio&gt;</span></span>
<span class="line"><span>   │  http://127.0.0.1:9333/proxy?url=...</span></span>
<span class="line"><span>   ▼</span></span>
<span class="line"><span>ZViewerCLI 本地 HTTP 代理</span></span>
<span class="line"><span>   │  注入本地 Bilibili Cookie + Referer / Origin / User-Agent</span></span>
<span class="line"><span>   ▼</span></span>
<span class="line"><span>Bilibili CDN（up to 大会员档位）</span></span></code></pre></div><ul><li><p><strong>优先使用 DASH。</strong> DASH（一种把音视频拆成分片、按需拉取的流式协议）在已连接 CLI 的高画质模式下会强制 <code>forceDash</code>，禁用 MP4 降级，音视频以 m4s 分离。<code>/resolve</code> 同时返回两种地址：原始 CDN URL（供 <code>/api/dash-mpd</code> 生成 MPD 喂给 MSE）和重写为本地代理的 URL。</p></li><li><p><strong>主地址失败时切换备用 CDN。</strong> <code>/proxy</code> 请求主 URL 失败后，按解析期缓存下来的 <code>backupUrl</code> 候选依次重试；同时透传 Range（分段请求头，用于拖动进度）；B站 CDN 偶尔返回 <code>application/json</code> 的视频数据，此时纠正为 <code>video/mp4</code>；上游超时 60s，连接池配置为 <code>MaxIdleConns=100 / PerHost=20</code>。</p></li><li><p><strong>清晰度档位。</strong> <code>qn</code> 是 B站表示清晰度的档位号，取值 127(8K)/126(杜比)/125(HDR)/120(4K)/116/112/80/74/64/32/16。请求参数为 <code>fnval = 16 | (VIP ? 128 : 0)</code>，qn=127 时再追加 8K 标志位；会员档白名单是 <code>[112,116,120,125,126,127]</code>。MP4 直链最高支持 1080P（<code>mp4MaxQn=80</code>）。</p></li><li><p><strong>服务端的 <code>/api/cli/resolve</code>。</strong> 这个接口用 CLI 请求头里自带的 B站 Cookie 做解析（Cookie 需含 SESSDATA），并设置 <code>skipCdnCheck: true</code>。实际视频流由用户本机浏览器经 CLI 拉取，服务器不需要校验 CDN 可达性，这样可以避免远程网络差异造成的错误降级。</p></li><li><p><strong>非会员的档位保护。</strong> 前端开启 CLI 且代理在线时会查询会员状态。如果用户不是会员却选了会员档（qn &gt; 80），会自动回落到 0，也就是跟随账号默认档位。</p></li></ul><p>解析结果有缓存：音频直链 TTL（生存时间，即缓存多久后失效）为 2 小时；VIP 状态缓存 5 分钟。</p><h2 id="前端接入点" tabindex="-1">前端接入点 <a class="header-anchor" href="#前端接入点" aria-label="Permalink to &quot;前端接入点&quot;">​</a></h2><p>前端在几个位置接入了 CLI，各自的行为如下表。</p><table tabindex="0"><thead><tr><th>场景</th><th>行为</th></tr></thead><tbody><tr><td>音乐视频背景</td><td><code>useMusicVideoBackground</code>：CLI 在线 → CLI 高画质 DASH；否则回退服务器 720P MP4</td></tr><tr><td>音乐音源</td><td><code>resolveBiliAudio</code>：CLI 开启且在线 → CLI DASH 音轨；否则服务器代理 MP4</td></tr><tr><td>一起看影片</td><td>房间开关 <code>cliEnabled</code> 打开时可用；<code>hostCliEnabled</code> 会经同步状态广播给观众（强制走 MP4 路径）</td></tr><tr><td>配置页入口</td><td><code>openCliSetup()</code> 打开 <code>http://127.0.0.1:9333/?server=&lt;api&gt;&amp;user=&lt;username&gt;</code>；CLI 侧读取参数预填，连接时用 POST <code>/api/connect</code> 上报</td></tr></tbody></table><h2 id="断线重连与心跳" tabindex="-1">断线重连与心跳 <a class="header-anchor" href="#断线重连与心跳" aria-label="Permalink to &quot;断线重连与心跳&quot;">​</a></h2><p>网络会抖动，服务器也可能短暂不可达，所以 CLI 侧和前端侧各有一套保活机制。</p><ul><li><p><strong>CLI 侧</strong>由服务器主导 ping/pong 心跳。<code>lastActivityAt</code> 超过 <code>pingInterval + pingTimeout</code>（下限 45s）时强制重连；<code>reconnectLoop</code> 采用指数退避，base 2s / max 60s，并叠加 ±25% 抖动（在算出的间隔上加一点随机偏移，避免大量客户端同时重连）。</p></li><li><p><strong>前端侧</strong>每 3s 轮询一次 <code>cli-list-agents</code>，同时监听 <code>cli-agent-available/unavailable/cli-agents</code> 事件实时刷新。</p></li></ul><h2 id="故障排查" tabindex="-1">故障排查 <a class="header-anchor" href="#故障排查" aria-label="Permalink to &quot;故障排查&quot;">​</a></h2><p>遇到问题可以按下表逐项检查。</p><table tabindex="0"><thead><tr><th>现象</th><th>检查</th></tr></thead><tbody><tr><td>配置页无法连接</td><td>服务器地址是否可达；CLI 是否保持运行（注册是内存态）；<code>-port</code> 是否被占用</td></tr><tr><td>代理列表为空</td><td>CLI 的 <code>user</code> 与网页登录用户名是否一致；CLI 是否已完成 <code>cli-register</code></td></tr><tr><td>高画质仍失败</td><td>Cookie 是否有效（网页端能看对应清晰度）；会员档是否被非会员保护回落；CLI 版本 ≥ 0.2.0</td></tr><tr><td>播放报 CORS</td><td>代理 URL host 是否被规范为 127.0.0.1（旧版 CLI 会误报页面 host）</td></tr></tbody></table>`,24)])])}const k=o(s,[["render",d]]);export{g as __pageData,k as default};
